-- LLM-drafted translations (needs_review = TRUE throughout) of Level 3's
-- lesson content (seeded by migration 0034), into the 7 non-English
-- locales — same posture as migrations 0021 and 0038.
INSERT INTO lesson_translations (lesson_id, locale, title, content) VALUES
    ('00000000-0000-0000-0000-000000002101', 'pcm', 'Grounding Techniques For Now-Now Moment', 'Grounding na small-small techniques wey dey help bring your mind back to wetin dey happen now when you feel too much, worry, or like say you no dey connect. The idea na to give your body clear, correct proof say you dey here, now, and you safe -- instead of to dey trapped inside memory or "wetin if" wahala.\n\nOne technique wey plenty people dey use na "5-4-3-2-1": call five things wey you fit see, four things wey you fit touch, three things wey you fit hear, two things wey you fit perceive through nose, and one thing wey you fit taste. Another one na just to press your leg for ground and notice the body feeling of touch and support.\n\nGrounding no dey wipe hard feelings comot, and e no suppose do that work. E dey create small window of steady mind so you fit respond to situation instead of make e carry you comot. Like any skill, e dey work better when you dey practice am for calm time, no be only for emergency.'),
    ('00000000-0000-0000-0000-000000002101', 'yo', 'Àwọn Ìlànà Gírámdínì Fún Àsìkò Lọ́wọ́lọ́wọ́', 'Gírámdínì jẹ́ àkójọ àwọn ìlànà tí ó rọrùn tí ó ń ràn ọ́ lọ́wọ́ láti mú àfiyèsí rẹ padà sí àsìkò lọ́wọ́lọ́wọ́ nígbà tí o bá nímọ̀lára bíi pé ó pọ̀ jù, àníyàn, tàbí bí ẹni pé o kò sopọ̀ mọ́. Èrò náà ni láti fún ètò ara rẹ ní ẹ̀rí tí ó ṣe kedere pé o wà níbí, ní báyìí, àti pé o wà láàbò -- dípò kí o dí mọ́ inú ìrántí tàbí yíyí ká "kín ló bá jẹ́ pé..."\n\nỌ̀kan lára àwọn ìlànà tí ó gbajúmọ̀ ni "5-4-3-2-1": pe orúkọ ohun márùn-ún tí o lè rí, ohun mẹ́rin tí o lè fọwọ́ kàn, ohun mẹ́ta tí o lè gbọ́, ohun méjì tí o lè gbóòórùn, àti ohun kan tí o lè tọ́wò. Òmíràn ni láti fi ẹsẹ̀ rẹ tẹ ilẹ̀ kí o sì ṣàkíyèsí ìmọ̀lára ara nípa ìfarakanra àti àtìlẹ́yìn.\n\nGírámdínì kò ń pa àwọn ìmọ̀lára tó le kúrò, kò sì jẹ́ fún èyí. Ó ń dá fèrèsé ìdúróṣinṣin kékeré sílẹ̀ kí o bàa lè dáhùn sí ipò kan dípò kí ó gbé ọ lọ. Gẹ́gẹ́ bí ọgbọ́n èyíkéyìí, ó máa ń ṣiṣẹ́ dáadáa nígbà tí a bá ń lò ó nígbà tí ara balẹ̀, kì í ṣe nígbà pàjáwìrì nìkan.'),
    ('00000000-0000-0000-0000-000000002101', 'ha', 'Dabarun Daidaitawa Da Lokacin Yanzu', 'Daidaitawa (grounding) tsari ne na dabaru masu sauki da ke taimaka wa maida hankalinka zuwa lokacin yanzu idan ka ji an mamaye ka, kana cikin damuwa, ko ka rabu da kanka. Manufar ita ce ba wa tsarin jijiyoyinka hujja mai tabbaci cewa kana nan, yanzu, kuma lafiya -- maimakon kamawa cikin tunawa ko zagayowar "me zai faru idan."\n\nDabara daya da aka saba amfani da ita ita ce "5-4-3-2-1": ambaci abubuwa guda biyar da zaka iya gani, hudu da zaka iya taba, uku da zaka iya ji, biyu da zaka iya jin warinsu, da abu daya da zaka iya dandana. Wata dabarar kuma ita ce kawai danna kafafunka a kasa ka lura da jin dadin jiki na tabawa da goyan baya.\n\nDaidaitawa ba ya share jin zafi masu wuya, kuma ba haka manufarsa take ba. Yana kirkiro karamin taga na kwanciyar hankali domin ka iya mayar da martani ga wani yanayi maimakon a dauke ka tare da shi. Kamar kowace fasaha, yana aiki da kyau idan aka yi atisaye a lokutan natsuwa, ba kawai gaggawa ba.'),
    ('00000000-0000-0000-0000-000000002101', 'ig', 'Ụzọ Nchekwa Ahụ-Mmụọ Maka Oge Ugbu A', 'Nchekwa ahụ-mmụọ (grounding) bụ otu ụdị ụzọ dị mfe nke na-enyere aka ịweghachi uche gị n''oge ugbu a mgbe ị nwere mmetụta nke na-eju gị eju, ihe ụjọ, ma ọ bụ ọpụpụ n''ozi. Echiche ahụ bụ inye usoro akwara gị ihe àmà doro anya na ị nọ ebe a, ugbu a, na n''udo -- kama ịbụ onye ncheta ma ọ bụ ịgba gburugburu ihe "gịnịmaa ọ bụrụ na."\n\nOtu usoro a na-ejikarị bụ "5-4-3-2-1": kpọọ aha ihe ise ị nwere ike ịhụ, anọ ị nwere ike imetụ aka, atọ ị nwere ike ịnụ, abụọ ị nwere ike ísè, na otu ihe ị nwere ike ịtọ ire. Ọzọkwa bụ naanị ịmanye ụkwụ gị n''ala wee mara mmetụta anụ ahụ nke mmetụta na nkwado.\n\nNchekwa ahụ-mmụọ anaghị ehichapụ mmetụta siri ike, ọ bụghịkwa ihe ọ bụ maka ime otú ahụ. Ọ na-emepụta obere oghere nke nkwụsiri ike ka ị nwee ike ịzaghachi ọnọdụ kama ka ọ kpụrụ gị. Dị ka nkà ọ bụla, ọ na-arụ ọrụ nke ọma mgbe a na-eme ya n''oge udo, ọ bụghị naanị oge mberede.'),
    ('00000000-0000-0000-0000-000000002101', 'fr', 'Techniques d''Ancrage pour le Moment Présent', 'L''ancrage est un ensemble de techniques simples qui aident à ramener votre attention au moment présent lorsque vous vous sentez dépassé, anxieux, ou déconnecté. L''idée est de donner à votre système nerveux une preuve claire et concrète que vous êtes ici, maintenant, et en sécurité -- plutôt que piégé dans un souvenir ou une spirale de « et si ».\n\nUne technique largement utilisée est le « 5-4-3-2-1 » : nommez cinq choses que vous pouvez voir, quatre que vous pouvez toucher, trois que vous pouvez entendre, deux que vous pouvez sentir, et une que vous pouvez goûter. Une autre consiste simplement à presser vos pieds contre le sol et à remarquer la sensation physique de contact et de soutien.\n\nL''ancrage n''efface pas les émotions difficiles, et ce n''est pas son but. Il crée une petite fenêtre de stabilité qui vous permet de répondre à une situation plutôt que d''être emporté par elle. Comme toute compétence, elle fonctionne mieux lorsqu''elle est pratiquée pendant les moments calmes, pas seulement en cas d''urgence.'),
    ('00000000-0000-0000-0000-000000002101', 'sw', 'Mbinu za Kujiweka Imara kwa Wakati Uliopo', 'Kujiweka imara (grounding) ni mkusanyiko wa mbinu rahisi zinazosaidia kurejesha makini yako katika wakati uliopo unapohisi kulemewa, wasiwasi, au kutounganika. Wazo ni kuupa mfumo wako wa neva ushahidi wazi na thabiti kuwa upo hapa, sasa, na salama -- badala ya kunaswa katika kumbukumbu au mzunguko wa "vipi ikiwa."\n\nMbinu moja inayotumika sana ni "5-4-3-2-1": taja vitu vitano unavyoweza kuona, vinne unavyoweza kugusa, vitatu unavyoweza kusikia, viwili unavyoweza kunusa, na kimoja unachoweza kuonja. Nyingine ni kukandamiza miguu yako sakafuni tu na kutambua hisia halisi ya mguso na tegemeo.\n\nKujiweka imara hakufuti hisia ngumu, na haikusudiwi kufanya hivyo. Hutengeneza dirisha dogo la utulivu ili uweze kuitikia hali badala ya kusombwa nayo. Kama ujuzi wowote, hufanya kazi vizuri zaidi kwa mazoezi wakati wa amani, si dharura tu.'),
    ('00000000-0000-0000-0000-000000002101', 'ar', 'تقنيات التأريض للحظة الحاضرة', 'التأريض هو مجموعة من التقنيات البسيطة التي تساعد على إعادة انتباهك إلى اللحظة الحاضرة عندما تشعر بالإرهاق أو القلق أو الانفصال. الفكرة هي إعطاء جهازك العصبي دليلًا واضحًا وملموسًا على أنك هنا، الآن، وآمن -- بدلًا من الوقوع في ذكرى أو دوامة "ماذا لو".\n\nإحدى التقنيات الشائعة الاستخدام هي "5-4-3-2-1": سمِّ خمسة أشياء يمكنك رؤيتها، وأربعة يمكنك لمسها، وثلاثة يمكنك سماعها، واثنين يمكنك شمهما، وواحدًا يمكنك تذوقه. تقنية أخرى هي ببساطة الضغط بقدميك على الأرض وملاحظة الإحساس الجسدي بالتلامس والدعم.\n\nالتأريض لا يمحو المشاعر الصعبة، وليس هذا هو الغرض منه. إنه يخلق نافذة صغيرة من الاستقرار حتى تتمكن من الاستجابة لموقف ما بدلًا من الانجراف معه. مثل أي مهارة، يعمل بشكل أفضل مع الممارسة خلال اللحظات الهادئة، وليس فقط في حالات الطوارئ.'),

    ('00000000-0000-0000-0000-000000002102', 'pcm', 'Sleep and the Nervous System', 'Sleep and trauma recovery dey connect well-well. Nervous system wey no feel safe dey always find am hard to shut down well, e go cause light sleep wey no complete, you go dey wake many times, or you go dey get strong bad dreams -- and dis one go make your nervous system react more the next day. E fit turn to hard cycle.\n\nSome practical things fit help show your body say e safe when sleep time reach: steady routine before you sleep, reduce light one hour before bed, and no review stress matter just before you sleep. None of dis one na cure by itself, but to dey consistent matter pass any one technique.\n\nIf sleep wahala too much or e no dey stop, e good make you talk to health worker about am -- dis lesson na general teaching, e no fit replace proper sleep check-up.'),
    ('00000000-0000-0000-0000-000000002102', 'yo', 'Oorun àti Ètò Ara', 'Oorun àti ìmúpadàbọ̀sípò ìpalára-ọkàn ní ìsopọ̀ pẹ̀kípẹ̀kí. Ètò ara tí kò nímọ̀lára láàbò sábà máa ń ní ìṣòro láti pa dé pátápátá, èyí tí ó ń yọrí sí oorun fàfàfà, títa jí lálẹ́ lọ́pọ̀lọ́pọ̀, tàbí àlá tí ó le tí ó ń dààmú -- èyí tí ó sì ń mú kí ètò ara ṣe àfiyèsí jù ní ọjọ́ kejì. Ó lè di àyípo tí ó le.\n\nÀwọn ìdúró tó wúlò kan ń ràn ọ́ lọ́wọ́ láti fi hàn fún ara rẹ pé ó wà láàbò nígbà oorun: àṣà tí a máa ń tẹ̀lé déédéé ṣáájú oorun, dídín ìmọ́lẹ̀ kù wákàtí kan ṣáájú kí o tó lọ sùn, àti yíyẹra fún ríronú lé ọ̀rọ̀ másùnmáwo ṣáájú oorun. Kò sí ọ̀kan lára wọn tí ó jẹ́ ìwòsàn fúnra rẹ̀, ṣùgbọ́n ìdúró-ṣinṣin ṣe pàtàkì ju ìlànà kan ṣoṣo lọ.\n\nTí ìṣòro oorun bá le tàbí tí ó bá ń bá a lọ, ó yẹ kí a bá oníṣègùn sọ̀rọ̀ nípa rẹ̀ -- ẹ̀kọ́ yìí jẹ́ ìmọ̀ gbogbogbòò, kì í ṣe ìyẹ̀wò oorun ní ti ìṣègùn.'),
    ('00000000-0000-0000-0000-000000002102', 'ha', 'Barci da Tsarin Jijiyoyi', 'Barci da farfadowa daga rauni suna da alaka ta kusa. Tsarin jijiyoyi da ba ya jin lafiya galibi yana gwagwarmaya ya kashe sosai, wanda ke kawo barci mara zurfi, tashi akai-akai, ko mafarkai masu tayar da hankali -- wanda kuma ke sa tsarin jijiyoyi ya zama mai saurin amsawa washegari. Zai iya zama zagaye mai wahala.\n\nWasu abubuwa masu amfani suna taimakawa nuna wa jikinka cewa yana lafiya a lokacin kwanciya: tsayayyen tsari kafin barci, rage haske sa''a daya kafin kwanciya, da gujewa tunani kan batutuwan damuwa kafin barci. Babu ɗayansu da ke warkarwa shi kadai, amma dagewa ta fi muhimmanci fiye da kowace dabara guda.\n\nIdan matsalolin barci sun yi tsanani ko suna ci gaba, ya kamata a tattauna hakan da mai bada kiwon lafiya -- wannan darasin ilimi ne na gaba daya, ba madadin bincike na asibiti kan barci ba.'),
    ('00000000-0000-0000-0000-000000002102', 'ig', 'Ụra na Usoro Akwara', 'Ụra na nnweghachi site na mmerụ ahụ-mmụọ jikọrọ ọnụ nke ọma. Usoro akwara nke na-enweghị mmetụta nchekwa na-anọkarị na-agba mbọ ịgwụsị kpamkpam, nke na-eduga na ụra na-adịghị omimi, ịnọ na-eteta mgbe niile, ma ọ bụ nrọ dị egwu -- nke na-emekwa ka usoro akwara zaa azịza ọzọ n''echi ya. O nwere ike ịghọ okirikiri siri ike.\n\nỤfọdụ ihe ndabere bara uru na-enyere aka igosi ahụ gị na ọ nọ n''udo n''oge ịrahụ ụra: usoro n''udo tupu ị rahụ ụra, ibelata ìhè otu awa tupu ịrahụ ụra, na izere ịtụgharị uche na okwu na-ewute ozugbo tupu ụra. Ọ nweghị nke n''ime ha bụ ọgwụgwọ naanị ya, mana ịnọgide na-eme otu ihe dị mkpa karịa otu ụzọ ọ bụla.\n\nỌ bụrụ na nsogbu ụra siri ike ma ọ bụ na-aga n''ihu, ọ bara uru ikwu maka ya na onye na-eweta ahụike -- nkuzi a bụ agụmakwụkwọ izugbe, ọ bụghị ihe na-anọchi anya nyocha ụra ahụike.'),
    ('00000000-0000-0000-0000-000000002102', 'fr', 'Le Sommeil et le Système Nerveux', 'Le sommeil et la guérison du traumatisme sont étroitement liés. Un système nerveux qui ne se sent pas en sécurité a souvent du mal à se mettre complètement en veille, ce qui entraîne un sommeil plus léger et plus fragmenté, des réveils fréquents, ou des rêves vifs et pénibles -- ce qui à son tour rend le système nerveux plus réactif le lendemain. Cela peut devenir un cycle difficile.\n\nCertains repères pratiques aident à signaler la sécurité à votre corps à l''heure du coucher : une routine de détente régulière, tamiser les lumières une heure avant de dormir, et éviter de ressasser des sujets stressants juste avant de dormir. Aucun de ces éléments n''est un remède en soi, mais la régularité compte plus que n''importe quelle technique isolée.\n\nSi les difficultés de sommeil sont sévères ou persistantes, il vaut la peine d''en parler à un professionnel de santé -- cette leçon est une éducation générale, pas un substitut à une évaluation clinique du sommeil.'),
    ('00000000-0000-0000-0000-000000002102', 'sw', 'Usingizi na Mfumo wa Neva', 'Usingizi na kupona kutoka kwa kiwewe vimeunganishwa kwa karibu. Mfumo wa neva usiohisi salama mara nyingi hupambana kuzima kabisa, hali inayopelekea usingizi mwepesi zaidi, uliogawanyika, kuamka mara kwa mara, au ndoto kali zenye kusumbua -- jambo ambalo kwa upande wake hufanya mfumo wa neva kuwa na mwitikio zaidi siku inayofuata. Unaweza kuwa mzunguko mgumu.\n\nVianzio vichache vya vitendo husaidia kuashiria usalama kwa mwili wako wakati wa kulala: utaratibu thabiti wa kutuliza kabla ya kulala, kupunguza mwanga saa moja kabla ya kulala, na kuepuka kukagua mada za msongo muda mfupi kabla ya kulala. Hakuna hata moja kati ya hivi iliyo tiba yenyewe, lakini uthabiti una umuhimu zaidi kuliko mbinu moja tu.\n\nIkiwa matatizo ya usingizi ni makali au yanaendelea, inafaa kuyazungumza na mtoa huduma za afya -- somo hili ni elimu ya jumla, si mbadala wa tathmini ya kimatibabu ya usingizi.'),
    ('00000000-0000-0000-0000-000000002102', 'ar', 'النوم والجهاز العصبي', 'يرتبط النوم بالتعافي من الصدمة ارتباطًا وثيقًا. غالبًا ما يكافح الجهاز العصبي الذي لا يشعر بالأمان لإيقاف نفسه بالكامل، مما يؤدي إلى نوم أخف وأكثر تجزؤًا، واستيقاظ متكرر، أو أحلام مزعجة وحية -- مما يجعل بدوره الجهاز العصبي أكثر تفاعلًا في اليوم التالي. يمكن أن يصبح هذا دورة صعبة.\n\nتساعد بعض المرتكزات العملية على إشارة الأمان لجسدك عند النوم: روتين هدوء ثابت، تخفيف الإضاءة قبل ساعة من النوم، وتجنب مراجعة الموضوعات المرهقة قبل النوم مباشرة. لا شيء من هذه وحده علاج، لكن الاستمرارية أهم من أي تقنية منفردة.\n\nإذا كانت صعوبات النوم شديدة أو مستمرة، فمن المفيد طرح ذلك مع مقدم رعاية صحية -- هذا الدرس تثقيف عام، وليس بديلاً عن تقييم سريري للنوم.'),

    ('00000000-0000-0000-0000-000000002103', 'pcm', 'Everyday Stress Management', 'Regulation no be for crisis time only -- na everyday habit wey dey make sure say your normal stress no dey build up without you sabi, until small thing go later cause am to burst. Regular movement, even small waka, dey help your body use stress hormone wey your body don already produce but e never get chance to use the way e for use am if, say, you dey run comot from danger.\n\nBreath na another tool wey dey available: slow, long exhale (wey pass your inhale) dey activate your body calming response. Common pattern na to breathe in for four count and breathe out for six, you go repeat am for one or two minutes.\n\nThe goal no be to comot stress completely -- some stress na normal part of life. Na to build small reliable tools wey no need plenty effort, wey you fit use before stress gather pass wetin you fit manage.'),
    ('00000000-0000-0000-0000-000000002103', 'yo', 'Ìṣàkóso Másùnmáwo Ojoojúmọ́', 'Ìṣàtúnṣe kì í ṣe fún àsìkò ìṣòro ńlá nìkan -- ó tún jẹ́ àwọn àṣà ojoojúmọ́ tí ó ń rí i dájú pé másùnmáwo rẹ ìpìlẹ̀ kò kóra jọ láìsí àkíyèsí títí tí ohun kékeré kan yóò fi mú kí ó bu jáde. Ìgbéra déédéé, kódà rírìn kúkúrú, ń ṣe ìrànlọ́wọ́ láti lo àwọn homonu másùnmáwo tí ara rẹ ti ṣe àmúṣe tí kò tí ì ní àǹfààní láti lò gẹ́gẹ́ bí ó ti máa ń lò ó lẹ́yìn, bí àpẹẹrẹ, sísá kúrò nínú ewu.\n\nẸ̀mí jẹ́ irinṣẹ́ mìíràn tí ó rọrùn láti rí: ìmí jíjáde lọ́ra, gígùn (tí ó gùn ju ìmí wíwọlé rẹ lọ) ń mú ìdáhùn ìtura ara rẹ ṣiṣẹ́. Àpẹẹrẹ tí ó wọ́pọ̀ ni mímí wíwọlé fún ìṣẹ́jú mẹ́rin àti mímí jíjáde fún ìṣẹ́jú mẹ́fà, tí a ó máa ṣe fún ìṣẹ́jú kan tàbí méjì.\n\nÈròǹgbà náà kì í ṣe láti mú másùnmáwo kúrò pátápátá -- másùnmáwo kan jẹ́ apá kan ìgbésí ayé lásán. Ó jẹ́ láti kọ́ àwọn irinṣẹ́ onígbẹ́kẹ̀lé díẹ̀ tí kò nílò ipá púpọ̀, tí o lè lò kí másùnmáwo tó kóra jọ ju bí o ṣe lè ṣàkóso rẹ̀ lọ.'),
    ('00000000-0000-0000-0000-000000002103', 'ha', 'Sarrafa Damuwa Ta Yau Da Kullum', 'Daidaitawa ba don lokutan rikici kadai ba ne -- hakika dabi''un yau da kullum ne da ke hana damuwar ka ta asali ta taru ba tare da an lura ba har sai wani karamin abu ya sa ta zub da ruwa. Motsi na yau da kullum, ko da gajeriyar tafiya, yana taimakawa wajen amfani da hormonin damuwa da jikinka ya samar amma bai taba samun dama ya yi amfani da su ba yadda zai yi bayan, misali, gudu daga hatsari.\n\nNumfashi wata hanyar da ake samu cikin sauki ce: fitar numfashi a hankali, na dogon lokaci (wanda ya fi na shaka tsayi) yana kunna martanin natsuwa na jikinka. Tsari na kowa shi ne shaka na kidaya hudu da fitarwa na kidaya shida, ana maimaitawa na minti daya ko biyu.\n\nManufar ba ta kawar da damuwa gaba daya ba ne -- wasu damuwa bangare ne na yau da rayuwa. Manufar ita ce ginawa dabaru kalilan masu dogaro, marasa bukatar kokari mai yawa, da za ka iya amfani da su kafin damuwa ta tara fiye da yadda za ka iya sarrafawa.'),
    ('00000000-0000-0000-0000-000000002103', 'ig', 'Njikwa Nchegbu Kwa Ụbọchị', 'Nhazi abụghị naanị maka oge nsogbu -- ọ bụkwa omume ndị kwa ụbọchị na-eme ka nchegbu gị izugbe ghara ikpokọta n''amaghị ama ruo mgbe obere ihe ga-eme ka ọ wụpụta. Mmegharị ahụ mgbe niile, ọbụlagodi mbịgharị nta, na-enyere aka iji homone nchegbu ahụ gị mepụtara mana enwetaghị ohere iji ya mee ihe dịka ọ ga-eme, dịka ọmụmaatụ, mgbe ị na-agba ọsọ site n''ihe ize ndụ.\n\nUme bụ ngwá ọrụ ọzọ dị mfe iji nweta: ịkwụpụ ume nwayọ, nke dị ogologo (karịa ike gị ikuru ume) na-akpalite azịza nkwụsi ike nke ahụ gị. Usoro a na-ahụkarị bụ ikuru ume ruo ọnụ ọgụgụ anọ na ikwụpụ ya ruo isii, na-emegharị ya nwa nkeji ọ bụ abụọ.\n\nEbumnuche ahụ abụghị iwepụ nchegbu kpamkpam -- nchegbu ụfọdụ bụ akụkụ nkịtị nke ndụ. Ọ bụ iwulite ngwá ọrụ ole na ole a pụrụ ịdabere na ya, nke na-adịghị achọ mgbalị dị ukwuu, nke ị nwere ike iji tupu nchegbu akpakọta karịa ka ọ dị mfe ijikwa.'),
    ('00000000-0000-0000-0000-000000002103', 'fr', 'Gestion du Stress au Quotidien', 'La régulation ne concerne pas seulement les moments de crise -- ce sont aussi les habitudes quotidiennes qui empêchent votre stress de base de s''accumuler sans que vous le remarquiez, jusqu''à ce qu''un petit événement le fasse déborder. Un mouvement régulier, même une courte marche, aide à métaboliser les hormones de stress que votre corps a produites mais n''a jamais pu utiliser comme il le ferait après, par exemple, avoir fui un danger.\n\nLa respiration est un autre outil accessible : des expirations lentes et prolongées (plus longues que l''inspiration) activent la réponse apaisante de votre corps. Un schéma courant consiste à inspirer en comptant jusqu''à quatre et à expirer en comptant jusqu''à six, répété pendant une ou deux minutes.\n\nL''objectif n''est pas d''éliminer le stress -- un certain stress fait normalement partie de la vie. Il s''agit de développer quelques outils fiables et peu exigeants que vous pouvez utiliser avant que le stress ne s''accumule au-delà de ce qui semble gérable.'),
    ('00000000-0000-0000-0000-000000002103', 'sw', 'Kudhibiti Msongo wa Kila Siku', 'Udhibiti sio tu kwa nyakati za dharura -- ni pia tabia za kila siku zinazozuia msongo wako wa msingi kujikusanya bila kutambuliwa hadi jambo dogo litakapolifanya lifurike. Mwendo wa mara kwa mara, hata kutembea kidogo, husaidia kuvunja homoni za msongo ambazo mwili wako ulizalisha lakini haukupata nafasi ya kuzitumia jinsi ungefanya baada ya, kwa mfano, kukimbia hatari.\n\nPumzi ni chombo kingine kinachopatikana kwa urahisi: kutoa pumzi polepole na kwa muda mrefu (zaidi ya unapovuta) huamsha mwitikio wa utulivu wa mwili wako. Mfumo wa kawaida ni kuvuta hewa kwa hesabu nne na kutoa kwa hesabu sita, ukirudiwa kwa dakika moja au mbili.\n\nLengo si kuondoa msongo kabisa -- msongo fulani ni sehemu ya kawaida ya maisha. Ni kujenga zana chache za kutegemewa, zisizohitaji juhudi kubwa, unazoweza kuzitumia kabla msongo haujakusanyika kupita kiwango unachoweza kudhibiti.'),
    ('00000000-0000-0000-0000-000000002103', 'ar', 'إدارة التوتر اليومي', 'التنظيم ليس فقط للحظات الأزمات -- بل هو أيضًا العادات اليومية التي تمنع تراكم توترك الأساسي دون ملاحظة حتى يتسبب أمر صغير في فيضانه. الحركة المنتظمة، حتى المشي القصير، تساعد على استقلاب هرمونات التوتر التي أنتجها جسدك لكنه لم يحصل على فرصة لاستخدامها كما كان سيفعل بعد، مثلاً، الهروب من خطر.\n\nالتنفس أداة أخرى سهلة المنال: الزفير البطيء والممتد (أطول من الشهيق) ينشط استجابة الهدوء في جسدك. النمط الشائع هو الشهيق لأربع عدات والزفير لست عدات، يتكرر لمدة دقيقة أو دقيقتين.\n\nالهدف ليس القضاء على التوتر -- بعض التوتر جزء طبيعي من الحياة. الهدف هو بناء أدوات قليلة موثوقة وقليلة الجهد يمكنك اللجوء إليها قبل أن يتراكم التوتر متجاوزًا ما يمكن التحكم فيه.');

INSERT INTO quiz_question_translations (question_id, locale, text) VALUES
    ('00000000-0000-0000-0000-000000002301', 'pcm', 'Wetin be the goal of grounding technique like "5-4-3-2-1"?'),
