    ('00000000-0000-0000-0000-000000002302', 'ha', 'Me ya sa rauni zai iya sa barci ya fi wahala?'),
    ('00000000-0000-0000-0000-000000002302', 'ig', 'Gịnị mere mmerụ ahụ-mmụọ ga-eji mee ka ụra sie ike karịa?'),
    ('00000000-0000-0000-0000-000000002302', 'fr', 'Pourquoi le traumatisme peut-il rendre le sommeil plus difficile ?'),
    ('00000000-0000-0000-0000-000000002302', 'sw', 'Kwa nini kiwewe kinaweza kufanya usingizi kuwa mgumu zaidi?'),
    ('00000000-0000-0000-0000-000000002302', 'ar', 'لماذا يمكن أن تجعل الصدمة النوم أكثر صعوبة؟'),

    ('00000000-0000-0000-0000-000000002303', 'pcm', 'For the breathing pattern wey dem talk, which part of the breath dem extend?'),
    ('00000000-0000-0000-0000-000000002303', 'yo', 'Nínú ìlànà ìmí tí a ṣàpèjúwe, apá wo nínú ìmí ni a gùn sí i?'),
    ('00000000-0000-0000-0000-000000002303', 'ha', 'A cikin tsarin numfashin da aka bayyana, wane bangare na numfashin ne aka tsawaita?'),
    ('00000000-0000-0000-0000-000000002303', 'ig', 'N''usoro iku ume e kọwara, akụkụ ume wee dị ogologo?'),
    ('00000000-0000-0000-0000-000000002303', 'fr', 'Dans le schéma respiratoire décrit, quelle partie de la respiration est prolongée ?'),
    ('00000000-0000-0000-0000-000000002303', 'sw', 'Katika mfumo wa kupumua ulioelezwa, ni sehemu gani ya pumzi iliyoongezwa muda?'),
    ('00000000-0000-0000-0000-000000002303', 'ar', 'في نمط التنفس الموصوف، أي جزء من التنفس يتم إطالته؟');

